/* ============================================================
   CyberPath — разборы ответов (explanation).
   Подключается ПОСЛЕ js/data.js и навешивает поле `explanation`
   на задания по id. Хранится отдельно от data.js, чтобы правки
   разборов не конфликтовали с контентом курсов.

   Что писать в поле:
   • почему правильный ответ верный (с опорой на стандарты/механику);
   • почему остальные варианты не подходят.
   Разрешён HTML: <p>, <ul>/<ol>/<li>, <b>, <code>, <span class="yes|no">.
   Английский вариант — в js/en/*.js, поле extra.why.
   ============================================================ */
const EXPLANATIONS = {
  /* ---------- Основы кибербезопасности ---------- */
  cia_choice: `<p><span class="yes">Верно:</span> триада CIA — это <b>Confidentiality, Integrity, Availability</b>. «Масштабируемость» к ней отношения не имеет: это свойство архитектуры (расти вверх/вбок), а не цель безопасности.</p>
    <p>Проверка на других примерах: шифрование и ACL работают на конфиденциальность, подписанные хеши — на целостность, резервирование — на доступность. Всё, что не сводится к этим трём свойствам, — не часть триады.</p>`,

  cia_defense: `<p><span class="yes">Верно:</span> эшелонированная защита (Defense in Depth) — принцип, по которому безопасность строится несколькими независимыми слоями: сеть → хост → приложение → данные. Сбой одного слоя не раскрывает систему.</p>
    <ul><li><span class="no">Единая точка входа</span> — наоборот, концентрирует риск и создаёт единую точку отказа.</li>
    <li><span class="no">Безопасность через неясность</span> (Security through Obscurity) слоем не является: скрытые имена не мешают сканеру, а утечка конфигурации обесценивает всю схему.</li>
    <li><span class="no">Минимальный пароль</span> — качество одного элемента, а не архитектура защиты.</li></ul>`,

  pw_factor: `<p><span class="yes">Верно:</span> двухфакторная аутентификация требует факторы <b>разных типов</b>: что вы знаете (пароль) + что у вас есть (TOTP-код из приложения-аутентификатора).</p>
    <ul><li><span class="no">Пароль + контрольный вопрос</span> — оба фактора типа «знаю», а ответ на контрольный вопрос часто лежит в открытых источниках.</li>
    <li><span class="no">Длинный пароль + PIN</span> — снова «знаю» + «знаю», 2FA не получается.</li>
    <li><span class="no">Два разных пароля</span> — то же самое, оба фактора одного типа.</li></ul>`,

  ph_lever: `<p><span class="yes">Верно:</span> «срочность и угрозы» — базовый приём социальной инженерии. Цель — не дать жертве время на проверку: «счёт заблокируют через час», «полиция уже в пути».</p>
    <ul><li><span class="no">Вежливое приветствие</span> — наоборот, снижает бдительность и не создаёт давления.</li>
    <li><span class="no">Длинное письмо</span> читают внимательнее; длинный текст — маскировка, а не рычаг.</li>
    <li><span class="no">Ссылка на закон</span> может быть в тексте, но сама по себе не лишает жертву времени думать.</li></ul>`,

  ph_action: `<p><span class="yes">Верно:</span> единственно безопасный путь — открыть нужный адрес самому: зайти в приложение банка, набрать адрес вручную или позвонить на номер с карты. Ссылка из письма — недоверенный ввод.</p>
    <ul><li><span class="no">Перейти по ссылке и войти</span> — ровно то, что нужно атакующему: фишинговая страница с настоящей формой входа.</li>
    <li><span class="no">Ответить и спросить пароль</span> — злоумышленник часто сам просит пароль «для проверки».</li>
    <li><span class="no">Переслать друзьям</span> — типичный приём вирусного фишинга: письмо рассылают от вашего имени вашим контактам.</li></ul>`,

  /* ---------- Windows ---------- */
  cmd_choice: `<p><span class="yes">Верно:</span> <code>ls</code> — команда Linux/Unix, в стандартной консоли Windows её нет (вернётся «не является внутренней или внешней командой»). Windows использует <code>dir</code>.</p>
    <p>Остальные варианты — родные cmd: <code>dir</code> (список), <code>type</code> (вывод файла), <code>cls</code> (очистка экрана). В PowerShell <code>ls</code> работает как алиас <code>Get-ChildItem</code>, но в cmd — нет.</p>`,

  ps_enc: `<p><span class="yes">Верно:</span> <code>powershell -w hidden -enc …</code> — скрытое окно плюс base64-кодированная команда. Классический признак вредоносной цепочки: пользователь ничего не видит, а защите сложно понять, что именно запускается.</p>
    <p>Остальные варианты — штатная работа администратора: <code>Get-Help</code>, чтение файла и <code>Get-Service</code> встречаются в легитимных скриптах. Для детекта важен не сам факт команды, а связка <b>скрытое окно + base64 + подозрительный источник</b> (загрузка из интернета).</p>`,

  wu_choice: `<p><span class="yes">Верно:</span> служба, работающая от <b>NT AUTHORITY\\SYSTEM</b>, имеет максимальные права. Если пользователь может писать в её исполняемый файл, он подменяет бинарник — и код выполнится от SYSTEM при следующем старте службы. Это классический путь локального повышения привилегий.</p>
    <ul><li><span class="no">Файл станет больше</span> — размер не важен, важен контроль над содержимым.</li>
    <li><span class="no">Служба будет быстрее</span> — побочный эффект, а не суть атаки.</li>
    <li><span class="no">Ничего страшного</span> — наоборот, один из самых частых векторов LPE.</li></ul>`,

  /* ---------- Сети ---------- */
  tcp_telnet: `<p><span class="yes">Верно:</span> Telnet (порт 23) передаёт логин и пароль <b>открытым текстом</b> и не имеет ни шифрования, ни контроля целостности. Всё, что видно на проводе (или в чужом Wi-Fi), можно перехватить и подделать, поэтому сервис отключают, а удалённый доступ переводят на SSH.</p>
    <ul><li><span class="no">SSH (22)</span> — сам защищённый канал, его наоборот оставляют.</li>
    <li><span class="no">HTTPS (443)</span> — HTTP поверх TLS, содержимое шифруется.</li>
    <li><span class="no">DNS (53)</span> — хотя сам по себе открытый, пароли он в открытом виде не передаёт.</li></ul>`,

  tcp_match: `<p><span class="yes">Верно:</span> стандартные порты закреплены в реестре IANA (Service Name and Transport Protocol Port Number Registry). Их знание наизусть экономит время и на скане, и на триаже.</p>
    <ul><li><b>22</b> — SSH: удалённый доступ к shell, в том числе OpenSSH в Windows.</li>
    <li><b>53</b> — DNS: TCP для зон и больших ответов, UDP для обычных запросов.</li>
    <li><b>443</b> — HTTPS: HTTP поверх TLS.</li>
    <li><b>3389</b> — RDP: удалённый рабочий стол Windows; сам по себе не дыра, но частый вектор входа по украденным паролям.</li></ul>`,

  na_https: `<p><span class="yes">Верно:</span> HTTPS (TLS) и VPN шифруют содержимое, поэтому перехватчик в открытом Wi-Fi видит лишь метаданные (IP, SNI, объём), но не текст, пароли и cookies.</p>
    <ul><li><span class="no">Более длинный логин</span> не защищает канал: по HTTP пароль всё равно виден целиком.</li>
    <li><span class="no">Отключение cookies</span> убирает часть следов, но не шифрует трафик.</li>
    <li><span class="no">Инкогнито</span> влияет только на локальную историю, сеть не защищает.</li></ul>
    <p>Оговорка: HTTPS без проверки сертификата уязвим к MITM с подменой сертификата — поэтому проверку сертификата отключать нельзя.</p>`,

  na_segment: `<p><span class="yes">Верно:</span> сегментация делит сеть на изолированные зоны (VLAN, подсети, DMZ) с правилами фильтрации между ними. Компрометация одного сегмента не даёт автоматически доступа к остальным — это ограничение «blast radius» атаки.</p>
    <ul><li><span class="no">Дефрагментация</span> — про ускорение диска.</li>
    <li><span class="no">Балансировка</span> — про отказоустойчивость и распределение нагрузки.</li>
    <li><span class="no">Кэширование</span> — про скорость, не про изоляцию.</li></ul>`,

  /* ---------- Веб (OWASP) ---------- */
  ow_choice: `<p><span class="yes">Верно:</span> SQL-инъекция — это категория <b>Injection</b>: в Top 10:2021 она A03, в редакции 2025 — A05. Причина одна: пользовательские данные попадают в интерпретируемый код.</p>
    <ul><li><span class="no">Cryptographic Failures</span> — про слабое или отсутствующее шифрование и хранение паролей в открытом виде.</li>
    <li><span class="no">Logging Failures</span> (Security Logging and Alerting Failures) — про отсутствие логов и алертов: атака проходит незамеченной.</li>
    <li><span class="no">SSRF</span> — про запросы от имени сервера; в Top 10:2021 это была A10, в 2025 она вошла в A01.</li></ul>`,

  sql_priv: `<p><span class="yes">Верно:</span> ущерб от успешной SQLi ограничивает <b>минимальные привилегии</b> учётки БД: у неё должно быть ровно то, что нужно приложению. Тогда инъекция не даст <code>DROP</code>, а чтение чужих таблиц упрётся в права.</p>
    <ul><li><span class="no">Более длинный пароль админа сайта</span> защищает вход в админку, но не ограничивает ущерб уже выполненного SQL-запроса.</li>
    <li><span class="no">Отключение JavaScript</span> — клиентская мера, серверный SQL никуда не делся.</li>
    <li><span class="no">Более быстрый сервер</span> вообще не про безопасность.</li></ul>`,

  xss_defense: `<p><span class="yes">Верно:</span> главная мера — <b>экранирование вывода по контексту</b> (HTML-сущности для текста, атрибутов, JS и URL). Оно ломает payload: <code>&lt;script&gt;</code> попадает на страницу как текст, а не как исполняемый тег. CSP — второй слой, страховка от забытых мест.</p>
    <ul><li><span class="no">Более сложный пароль</span> — не имеет отношения к выводу данных.</li>
    <li><span class="no">HTTPS вместо HTTP</span> защищает канал от перехвата, но не от самого XSS: скрипт остаётся скриптом.</li>
    <li><span class="no">Сжатие страницы</span> не влияет на выполнение кода.</li></ul>`,

  wa_obscurity: `<p><span class="yes">Верно:</span> IDOR живёт на сервере. Прямой запрос к чужому объекту (например, <code>/users/42/invoice</code> после подмены 42 на 43) вернёт данные, если нет проверки «владелец объекта = текущий пользователь». Кнопка на клиенте — это UI, а не контроль доступа.</p>
    <ul><li><span class="no">Кнопку можно перекрасить</span> — вопрос косметики, не безопасности.</li>
    <li><span class="no">Браузер кэширует страницу</span> — не связано с доступом к чужому объекту.</li>
    <li><span class="no">JS работает медленно</span> — тем более повод проверять права на сервере, а не на клиенте.</li></ul>`,

  /* ---------- Пентест ---------- */
  eth_disclosure: `<p><span class="yes">Верно:</span> ответственный путь — сообщить владельцу приватно, приложить шаги воспроизведения и дать разумный срок на исправление (обычно 90 дней).</p>
    <ul><li><span class="no">Опубликовать эксплойт в твиттере</span> — срывает исправление и фактически помогает атакующим.</li>
    <li><span class="no">Продать на форуме</span> — незаконно и равнозначно продаже уязвимости.</li>
    <li><span class="no">Использовать для доступа</span> — уже противоправно: доступ получен без разрешения.</li></ul>`,

  meth_order: `<p><span class="yes">Верно порядок:</span> разведка → сканирование → эксплуатация → пост-эксплуатация → отчёт. Каждая фаза опирается на результат предыдущей: без разведки нет целей, без сканирования нет поверхности атаки, без отчёта ценности для заказчика нет.</p>
    <p>На практике фазы пересекаются (новые цели находят уже во время эксплуатации), но логика «сначала собираем информацию — потом ломаем — потом фиксируем» не меняется. Отчёт — не формальность: именно он превращает находки в управляемые риски.</p>`,

  /* ---------- Криптография, AD, реверс ---------- */
  enc_choice: `<p><span class="yes">Верно:</span> только шифрование (например, AES) делает содержимое недоступным без ключа. Base64, Hex и URL-encoding — это <b>кодирование</b>: алгоритм публичный, ключа нет, и любой декодирует строку за секунду. Их роль — транспорт и маскировка, а не защита.</p>
    <p>Типичная ошибка — «зашифровать» пароль через Base64 и считать его защищённым. Для паролей нужны медленные хеш-функции с солью (bcrypt, argon2, scrypt), для данных — AEAD-шифры (AES-GCM, ChaCha20-Poly1305).</p>`,

  pau_align: `<p><span class="yes">Верно:</span> SPF проверяет домен в <b>конверте</b> (MAIL FROM / Return-Path), то есть кто реально отправил письмо на уровне SMTP. Заголовок <code>From:</code> подделывается тривиально, поэтому SPF проходит, а пользователь видит чужой адрес.</p>
    <p>Чтобы закрыть этот разрыв, нужен <b>DMARC alignment</b>: домен в видимом From должен совпадать (с учётом Relaxed/Strict) с доменом, прошедшим SPF или DKIM. Именно alignment, а не сам SPF, привязывает видимого отправителя к домену.</p>`,

  pau_match: `<p><span class="yes">Верно:</span> механизмы решают разные задачи и потому дополняют друг друга.</p>
    <ul><li><b>SPF</b> — списком серверов в DNS: «кому вообще разрешено слать почту от домена». Проверяет конверт.</li>
    <li><b>DKIM</b> — криптографической подписью: «содержимое не меняли в пути», домен отправителя берётся из <code>d=</code>.</li>
    <li><b>DMARC</b> — политикой поверх обоих: что делать при несовпадении (none / quarantine / reject) и куда слать отчёты (rua).</li></ul>`,

  add_cg: `<p><span class="yes">Верно:</span> Credential Guard изолирует компоненты, работающие с паролями и Kerberos-билетами, в отдельной защищённой секции ОС. Даже получив код в режиме ядра, атакующий не вытащит LSASS-секреты (хеши, тикеты) напрямую — их выдаёт только брокер credentials.</p>
    <ul><li><span class="no">BitLocker</span> шифрует диск: спасает от кражи ноутбука, но не от дампа памяти.</li>
    <li><span class="no">Defender Firewall</span> фильтрует сетевые соединения, к краже учётных данных отношения не имеет.</li>
    <li><span class="no">UAC</span> разделяет права администратора, но секреты в памяти остаются доступны процессу пользователя.</li></ul>`,

  re_dynamic: `<p><span class="yes">Верно:</span> если код упакован или зашифрован, статический анализ видит только «обёртку»: ни строк, ни логики. Динамический анализ запускает образец и наблюдает реальное поведение — распакованный код в памяти, сетевые запросы, изменения файлов и реестра.</p>
    <ul><li><span class="no">Когда нет компьютера</span> — не техника анализа, а отсутствие возможности.</li>
    <li><span class="no">Когда файл маленький</span> — размер не показатель: 10 КБ может быть дроппером.</li>
    <li><span class="no">Всегда одинаково</span> — на практике техники дополняют друг друга: статика даёт гипотезы, динамика их проверяет.</li></ul>`,

  rea_antivm: `<p><span class="yes">Верно:</span> anti-VM / anti-sandbox-техники проверяют окружение: имя процесса, параметры реестра, MAC-адрес, наличие VMware-утилит, время с запуска. Обнаружив виртуалку, малварь обычно спит или завершается, чтобы аналитик не увидел реального поведения.</p>
    <p>Поэтому анализ проводят в нескольких средах (вредонастка, VM без VMware Tools, иногда физическая машина) — иначе получите пустой результат и сделаете неверный вывод о «безобидности» образца.</p>`,

  /* ---------- Форензика и фишинг ---------- */
  fo_image: `<p><span class="yes">Верно:</span> аналитик работает с <b>побитовой копией (образом)</b>, а оригинал оставляет нетронутым: на нём больше не работают, он зафиксирован в процессуальных документах и служит доказательством. Даже восстановление и анализ идут на копии или её форк-образе.</p>
    <ul><li><span class="no">С самим оригиналом диска</span> — нарушение процедуры: риск изменить единственный экземпляр улики.</li>
    <li><span class="no">С облачной версией</span> — удобно, но не даёт процессуальной ценности и хеша оригинала.</li>
    <li><span class="no">С распечаткой</span> — не бывает носителем цифровой улики.</li></ul>`,

  fo_poweroff: `<p><span class="yes">Верно:</span> при выключении питания теряется оперативная память: расшифрованные ключи (BitLocker/VeraCrypt), сессии, сетевые соединения и бесфайловый вредонос живут только в RAM. Поэтому сначала хост <b>изолируют от сети</b>, снимают дамп памяти и лишь затем выключают.</p>
    <p>Второй важный момент — порядок сбора по волатильности (NIST SP 800-61): процессы и реестр, память, сетевые соединения, диск, образы. Всё, что питается, испаряется при обесточивании.</p>`,

  ct_warn: `<p><span class="yes">Верно:</span> «сертификат недействителен» означает, что цепочку доверия не удалось проверить: истёк срок, неизвестный удостоверяющий центр, не совпало имя — либо трафик перехватили и подменили сертификат. На сайте банка вход по такому предупреждению — риск утечки логина и денег.</p>
    <p>Как действовать: открыть сайт вручную, посмотреть срок действия и издателя сертификата, при сомнениях позвонить в поддержку по номеру с карты. Игнорировать предупреждение нельзя — именно ради обхода этой проверки и работают MITM.</p>`,

  pha_zip: `<p><span class="yes">Верно:</span> пароль к архиву отправляет письмо целиком за пределы корпоративного шлюза: почтовый фильтр, антивирус и sandbox не видят содержимое, а пользователь сам вводит пароль из того же письма. Эта комбинация — нормальный почтовый этап малвари и BEC-атак.</p>
    <ul><li><span class="no">Он весит много</span> — техническая деталь, а не признак.</li>
    <li><span class="no">Пароль легко забыть</span> — про удобство пользователя.</li>
    <li><span class="no">Это стандартная практика</span> — нет: в бизнес-переписке архив с паролем из того же письма считается тревожным сигналом.</li></ul>`,

  pha_choice: `<p><span class="yes">Верно:</span> валидная DKIM-подпись сама по себе — не признак фишинга: она подтверждает, что письмо не меняли в пути и отправили с домена, чей приватный ключ использовался.</p>
    <p>Но оговорка: если злоупотребляющий аккаунт действительно находится в домене отправителя, DKIM будет валидным. Поэтому подпись — лишь один из сигналов и читается вместе с оценкой DMARC, доменом в ссылке и поведением страницы. Остальные варианты (срочность и угрозы, домен-двойник, просьба ввести пароль по ссылке) — классические красные флаги.</p>`,

  /* ---------- Харденинг, Blue Team, малварь ---------- */
  hdp_defaults: `<p><span class="yes">Верно:</span> Secure Defaults — принцип, по которому безопасное поведение является поведением «из коробки», а не результатом отдельной настройки. Если изделие требует ручной настройки, большинство пользователей её не сделает.</p>
    <ul><li><span class="no">Отключить пароли для удобства</span> — обратная цель: убирается сама полезная мера.</li>
    <li><span class="no">Дать всем права админа</span> — нарушает минимальные привилегии и расширяет поверхность атаки.</li>
    <li><span class="no">Открыть все порты</span> — нарушает принцип минимального сервиса.</li></ul>`,

  hdw_audit: `<p><span class="yes">Верно:</span> внедрение начинают в режиме <b>аудита</b> (AppLocker/WDAC: Audit, не Enforce): политика только пишет логи о том, что было бы заблокировано. Так вы собираете реальные сценарии и не останавливаете рабочие машины, а затем включаете Enforce постепенно, через исключения.</p>
    <ul><li><span class="no">Сразу блокировать всё</span> — почти гарантированно сломает рабочие процессы и подтолкнёт людей отключать политику.</li>
    <li><span class="no">С отключения антивируса</span> — снижает защиту.</li>
    <li><span class="no">С выдачи всем прав админа</span> — прямо противоположно политике минимальных привилегий.</li></ul>`,

  bts_ioa: `<p><span class="yes">Верно:</span> IOA — индикатор <i>поведения</i>: «Word порождает PowerShell с <code>-enc</code>» почти всегда означает вредоносную цепочку, хотя легальный софт так не делает.</p>
    <ul><li><span class="no">Хеш вредоносного файла</span> — конкретный IOC: перепаковать файл и сменить хеш легко.</li>
    <li><span class="no">IP C2-сервера</span> — IOC: адреса меняются, в том числе через динамический DNS.</li>
    <li><span class="no">Имя ключа реестра</span> — IOC: достаточно другого имени.</li></ul>
    <p>На практике IOA надёжнее IOC, потому что ловит класс атаки, а не конкретный артефакт — на этом стоят и Hunting, и модель AT&amp;CK.</p>`,

  bti_recover: `<p><span class="yes">Верно:</span> восстанавливают из <b>чистых проверенных бэкапов</b>, сделанных до инцидента: только так можно гарантировать, что малварь не вернулся вместе с системой. Перед возвратом в работу образ проверяют антивирусом и EDR.</p>
    <ul><li><span class="no">Из текущего состояния заражённой машины</span> — возвращает проблему и заодно теряет улики.</li>
    <li><span class="no">Из кэша браузера</span> — не источник систем и данных.</li>
    <li><span class="no">Ниоткуда, оставить как есть</span> — инцидент не закрывается, риск сохраняется.</li></ul>`,

  bti_order: `<p><span class="yes">Верно порядок (NIST SP 800-61 Rev. 2):</span> подготовка → обнаружение и анализ → сдерживание, устранение и восстановление → действия после инцидента.</p>
    <ul><li><b>Подготовка</b> — люди, процессы, инструменты и playbook-и до инцидента.</li>
    <li><b>Обнаружение и анализ</b> — подтвердить инцидент, оценить масштаб и критичность.</li>
    <li><b>Сдерживание, устранение и восстановление</b> — остановить распространение, удалить угрозу, вернуть работу из чистых бэкапов.</li>
    <li><b>Действия после инцидента</b> — разбор, выводы, обновление правил и обучение.</li></ul>
    <p>Цикл замкнут: выводы фазы 4 усиливают подготовку фазы 1. Действующая Rev. 3 (2025) переводит эти же идеи в термины NIST CSF 2.0.</p>`,

  bta_easiest: `<p><span class="yes">Верно:</span> хеш файла меняется при любой пересборке, упаковке или правке — атакующий пересчитывает его за секунды. Это самый «дешёвый» индикатор: стоит перекомпилировать малварь, и сигнал больше не сработает.</p>
    <p>Поэтому в Pyramid of Pain Д. Бьянко индикаторы идут от бесполезных к самым ценным: хеши → домены и IP → инструменты и артефакты на хосте → <b>TTP (поведение)</b>. Чем выше индикатор, тем сложнее атакующему подстроиться и тем больше следов он оставляет.</p>`,

  mwt_choice: `<p><span class="yes">Верно:</span> ransomware шифрует файлы пользователя и данных, а затем требует выкуп за ключ. Признаки: массовое шифрование с новым расширением, требование оплаты, иногда кража данных перед шифрованием (double extortion).</p>
    <ul><li><span class="no">Rootkit</span> — скрывает присутствие и даёт скрытый доступ, файлы обычно не портит.</li>
    <li><span class="no">Worm</span> — самораспространяется по сети; может шифровать, но его суть — распространение.</li>
    <li><span class="no">Spyware</span> — крадёт информацию, ничего не шифрует и не вымогает.</li></ul>`,

  mwl_vtwarn: `<p><span class="yes">Верно:</span> VirusTotal отправляет образ десяткам вендоров, и для участников без NDA с заказчиком файл может попасть в публичные коллекции — загруженный образ становится доступен другим.</p>
    <ul><li><span class="no">Это платно</span> — сервис бесплатный; ограничение не в цене.</li>
    <li><span class="no">Файл испортится</span> — образ не изменяют, его копируют.</li>
    <li><span class="no">Антивирусы не работают</span> — наоборот, ради обнаружения и загружают.</li></ul>
    <p>Правило: персональные данные, образцы с клиента и всё, что нельзя раскрывать, на VirusTotal не грузят. Для внутреннего анализа есть закрытые площадки (VirusTotal Private, Kaspersky OpenTIP, арендованные песочницы).</p>`,

  /* ---------- Флаги в песочнице: как добываются и что значат ---------- */
  cmd_flag: `<p><span class="yes">Верно:</span> флаг лежит в файле <code>secret.txt</code> в домашней папке песочницы. Путь: <code>dir</code> → <code>type secret.txt</code>.</p>
    <p>Приём: <code>dir</code> показывает, что лежит в текущем каталоге (невидимые файлы — <code>dir /a</code>), а <code>type</code> выводит текстовый файл. В реальной работе то же делают через <code>findstr</code> или сверкой хеша, когда нужно доказать, что содержимое не менялось.</p>`,

  nm_flag: `<p><span class="yes">Верно:</span> порт <b>1337</b> — единственный нестандартный в выводе <code>nmap 10.10.10.5</code> рядом с типовыми 135, 139, 445 и 3389.</p>
    <p>Логика: порты SMB (445), RPC (135), NetBIOS (139), RDP (3389) для Windows ожидаемы; незнакомый порт стоит проверить (<code>-sV</code> — версии, <code>curl</code> или <code>nc</code> — что там висит). Правильный вывод: необычный порт — не находка сама по себе, а повод спросить, кто его открыл и зачем.</p>`,

  enc_b64: `<p><span class="yes">Верно:</span> <code>Q1lCRVJ7YmFzZTY0X2lzX2Vhc3l9</code> декодируется в <code>CYBER{base64_is_easy}</code>. В песочнице: <code>base64 -d Q1lCRVJ7YmFzZTY0X2lzX2Vhc3l9</code>.</p>
    <p>Главный вывод: Base64 — кодирование, а не шифрование. Ключа нет, алгоритм публичный, поэтому любой «секрет» в Base64 читается мгновенно: так прячут, но не защищают.</p>`,

  adr_flag: `<p><span class="yes">Верно:</span> флаг <code>CYBER{ad_recon_ok}</code> находится в файле <code>Documents\\domain.txt</code>: <code>type Documents\\domain.txt</code>.</p>
    <p>Урок разведки AD: даже простой осмотр файлов даёт имя домена и контроллера (<code>CYBER.LOCAL</code>, <code>DC01</code>) — базу для дальнейшего перечисления. Легальный порядок такой работы: письменное разрешение и границы (Scope), затем сбор, а всё найденное фиксируется в отчёте, а не используется как «добыча».</p>`,

  res_b64: `<p><span class="yes">Верно:</span> строка <code>Q1lCRVJ7cmV2X2VuZ19zdHJpbmdzfQ==</code> декодируется в <code>CYBER{rev_eng_strings}</code>.</p>
    <p>Смысл приёма: в бинаре строки часто лежат открытым текстом, в том числе закодированные — так прячут адреса C2 и идентификаторы. Рабочий порядок: <code>strings</code> по файлу → поиск base64-подобных блоков → декодирование → проверка находки. Найденное становится IOC только после проверки.</p>`,

  res_rot: `<p><span class="yes">Верно:</span> ROT13 симметричен: <code>PLORE{ebg13_qrpbqrq}</code> после сдвига на 13 превращается в <code>CYBER{rot13_decoded}</code>.</p>
    <p>Общая идея для реверса: простые шифры без ключа (ROT13, XOR с константой, base64) встречаются и в малвари, и в CTF. Признак — строка, которая читается после простого преобразования. ROT13 удобен тем, что шифрование и расшифровка совпадают.</p>`,

  foa_flag: `<p><span class="yes">Верно:</span> в <code>Documents\\system.log</code> строка с флагом находится так: <code>findstr CYBER Documents\\system.log</code>.</p>
    <p>Практика триажа: сначала поиск по ключевому слову, затем по <b>Event ID</b> и по времени (±5 минут от инцидента) — так собирается таймлайн. В этом же файле видны признаки зачистки: событие <b>1102</b> означает, что журнал безопасности очистили, — само по себе это улика против легитимного администратора.</p>`,

  mwb_flag: `<p><span class="yes">Верно:</span> цепочка <code>netstat</code> → <code>reg query HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run</code> → <code>certutil -decode …</code> приводит к <code>CYBER{persistence_found}</code>: в ключе <code>Run</code> найден автозапуск <code>powershell -enc Q1lCRVJ7cGVyc2lzdGVuY2VfZm91bmR9</code>, который декодируется в флаг.</p>
    <p>Логика расследования: закрепление ищут по точкам автозапуска (Run, RunOnce, Startup, задачи, службы), подозрительные команды декодируют и проверяют. Шифрование аргумента — не защита: <code>certutil</code> и <code>base64 -d</code> показывают содержимое. Уборка: удалить значение Run, проверить хеш файла, найти источник заражения.</p>`,

  /* ---------- Остальные choice-задания ---------- */
  rp_active: `<p><span class="yes">Верно:</span> сканирование портов цели — активная разведка: вы отправляете пакеты чужой системе. Пассивные методы (whois, поиск, соцсети) обращаются только к публичным источникам и обычно отдельного разрешения не требуют, хотя правила RoE касаются и их.</p>
    <ul><li><span class="no">Чтение WHOIS</span> — публичные регистрационные данные.</li>
    <li><span class="no">Поиск в Google</span> — запросы к поисковику, тоже публичные данные.</li>
    <li><span class="no">Просмотр соцсетей</span> — публичный контент.</li></ul>
    <p>Активное сканирование требует разрешения и должно быть вписано в Scope: без него это уже может быть нарушением закона.</p>`,

  pte_exec: `<p><span class="yes">Верно:</span> Executive Summary — раздел отчёта для руководства: что произошло, каков риск понятными терминами и что делать. Без техники и без «payload».</p>
    <ul><li><span class="no">Payload</span> — полезная нагрузка, термин из эксплуатации.</li>
    <li><span class="no">Shellcode</span> — машинный код, детали для инженеров.</li>
    <li><span class="no">Changelog</span> — список изменений, к безопасности отношения не имеет.</li></ul>
    <p>Хороший отчёт для руководства: факты, оценка риска, влияние на бизнес, приоритизированные меры и сроки. Технические детали идут отдельным приложением для инженеров.</p>`,

  hash_broken: `<p><span class="yes">Верно:</span> MD5 сломан: в 2004 году показана практическая коллизия — два разных файла с одинаковым MD5. Плюс он слишком быстрый, поэтому возможен перебор по радужным таблицам. Для паролей и криптографической целостности непригоден.</p>
    <ul><li><span class="no">SHA-256</span> — актуальный стандарт для целостности.</li>
    <li><span class="no">argon2 / bcrypt</span> — современные медленные функции для паролей, стойкие к перебору.</li></ul>
    <p>Оговорка: как некриптографическая контрольная сумма (проверка случайных повреждений) MD5 ещё встречается — просто не для защиты.</p>`,

  asym_hybrid: `<p><span class="yes">Верно:</span> асимметрия решает задачу <i>обмена</i> ключом, но медленна; симметрия быстра, но требует общего секрета. Поэтому в TLS асимметрией согласуют ключ сессии, а трафик шифруют симметричным алгоритмом (AES-GCM, ChaCha20-Poly1305).</p>
    <ul><li><span class="no">Для красоты</span> — очевидно нет.</li>
    <li><span class="no">Чтобы было два пароля</span> — ключ и сертификат, но это не смысл схемы.</li>
    <li><span class="no">Асимметрия шифрует весь трафик целиком</span> — неверно: это медленно и непрактично.</li></ul>`,

  os_ethics: `<p><span class="yes">Верно:</span> подбор пароля к чужой почте — уже не «открытые источники», а активная атака на доступ. OSINT работает только с тем, что владелец сам сделал публичным, и не требует технического взлома.</p>
    <ul><li><span class="no">Чтение публичного профиля</span> — общедоступные данные (если нет пометки «только для друзей» и NDA).</li>
    <li><span class="no">Просмотр EXIF выложенного фото</span> — метаданные уже опубликованы вместе с файлом.</li>
    <li><span class="no">Поиск в Google</span> — публичные индексы.</li></ul>
    <p>Отдельно: агрегирование открытых данных о конкретном человеке может нарушать закон о приватности — это тоже ограничение метода.</p>`,

  op_privacy: `<p><span class="yes">Верно:</span> EXIF хранит геометки, модель камеры, дату и иногда серийник. Удаление метаданных перед публикацией убирает самый простой способ узнать, где вы были.</p>
    <ul><li><span class="no">Выкладывать больше фото</span> — больше метаданных и больше мест, где вас узнают.</li>
    <li><span class="no">Ставить один ник везде</span> — связывает профили и упрощает деанонимизацию.</li>
    <li><span class="no">Включить геометки</span> — прямо публикует ваши координаты.</li></ul>`,

  fom_why: `<p><span class="yes">Верно:</span> бесфайловый вредонос и расшифрованные ключи существуют только в оперативной памяти. Образ диска покажет следы работы, но не код в памяти и не ключи шифрования в памяти ядра.</p>
    <ul><li><span class="no">Диск слишком большой</span> — про объём, а не про содержимое улик.</li>
    <li><span class="no">RAM быстрее читается</span> — про скорость, а не про уникальность данных.</li>
    <li><span class="no">Диск зашифрован всегда</span> — неверно; и при шифровании нужен ключ, который тоже лежит в памяти.</li></ul>`,

  hdb_why: `<p><span class="yes">Верно:</span> большинство реальных взломов эксплуатируют уже известные и уже исправленные уязвимости — просто в окне между публикацией патча и его установкой. Своевременное обновление это окно закрывает.</p>
    <ul><li><span class="no">Патчи ускоряют компьютер</span> — не основная цель, хотя бывают исключения.</li>
    <li><span class="no">Так требует мода</span> — нет.</li>
    <li><span class="no">Чтобы менять интерфейс</span> — нет.</li></ul>
    <p>Практика: автоматизация обновлений, инвентаризация ПО, приоритет по CVSS и снятие с поддержки версий EOL — именно на них чаще всего строят атаки.</p>`,

  /* ---------- Разборы к question-заданиям: Основы ---------- */
  cia_ddos: `<p><span class="yes">Верно:</span> DDoS «кладёт» сервис: пользователи не могут получить страницу или API. Данные при этом не крадут и не подменяют — нарушается именно <b>доступность</b>.</p>
    <p>Контрпримеры: утечка базы — конфиденциальность, подмена реквизитов — целостность.</p>`,

  cia_leak: `<p><span class="yes">Верно:</span> утечка приватных данных раскрывает их посторонним, то есть нарушает <b>конфиденциальность</b>. Доступность при этом сохраняется (сервис работает), целостность не затрагивается (данные не меняли).</p>`,

  cia_abbr: `<p><span class="yes">Верно:</span> I — это <b>Integrity</b> (целостность): данные не должны изменяться незаметно. Проверяется хешами, цифровыми подписями и контролем версий.</p>`,

  cia_integrity: `<p><span class="yes">Верно:</span> подмена суммы перевода — классический пример нарушения <b>целостности</b>: данные изменились, и без проверки подписи это незаметно. Защита — цифровая подпись и независимая сверка реквизитов.</p>`,

  cia_risk: `<p><span class="yes">Верно:</span> классическая формула <b>Риск = Вероятность × Ущерб</b>. Она объясняет, почему маловероятную катастрофу и частую мелочь закрывают по-разному: умножаем два слагаемых, а не складываем страх.</p>`,

  cia_stride: `<p><span class="yes">Верно:</span> E в STRIDE — <b>Elevation of Privilege</b>, повышение привилегий: получение прав выше выданных. Пример — процесс рядового пользователя запускает код от SYSTEM или обычный аккаунт получает права администратора.</p>`,

  cia_nonrep: `<p><span class="yes">Верно:</span> это <b>неотказуемость</b> (non-repudiation): автор действия не может потом заявить, что этого не делал. Обеспечивается цифровыми подписями, неизменяемыми логами и хронометражем.</p>`,

  pw_2fa: `<p><span class="yes">Верно:</span> 2FA (Two-Factor Authentication) — двухфакторная аутентификация. Сокращение проверяется по смыслу: два фактора, а не «два пароля».</p>`,

  pw_attack: `<p><span class="yes">Верно:</span> <b>credential stuffing</b> — автоматическая подстановка утекших пар логин/пароль на другие сервисы. Работает, потому что люди используют один пароль на несколько сайтов; защита — уникальные пароли в менеджере и MFA.</p>`,

  pw_spray: `<p><span class="yes">Верно:</span> <b>password spraying</b> — перебор одним популярным паролем по множеству учёток, чтобы обойти блокировку после серии неудачных попыток. Защита — MFA, мониторинг входов и блокировка по риску, а не только по числу попыток.</p>`,

  pw_entropy: `<p><span class="yes">Верно:</span> <b>длину</b>. Каждый дополнительный символ умножает число комбинаций, а замена букв на символы расширяет алфавит лишь в несколько раз. Правило NIST SP 800-63B: не меньше 15 символов для парольной фразы.</p>`,

  pw_best: `<p><span class="yes">Верно:</span> <b>менеджер паролей</b> хранит уникальные пароли для каждого сайта и убирает необходимость запоминать их. Бонус — автозаполнение и защита от фишинга: поддельный домен не совпадёт с сохранённой записью.</p>`,

  pw_storage: `<p><span class="yes">Верно:</span> это <b>соль</b> (salt) — случайная уникальная строка, добавляемая к паролю перед хешированием. Одинаковые пароли дают разные хеши, а перебор по радужным таблицам перестаёт работать.</p>`,

  ph_domain: `<p><span class="yes">Верно:</span> <code>paypa1.com</code> — в имени цифра <b>1</b> вместо буквы <code>l</code> («paypal»). Так работают домены-двойники: расстояние до настоящего бренда минимально, а домен принадлежит атакующему.</p>`,

  ph_realdomain: `<p><span class="yes">Верно:</span> настоящий домен здесь — <code>secure-login.ru</code>. Всё, что стоит левее (например <code>paypal.com.</code>), — поддомены, которые злоумышленник контролирует. Проверяйте домен справа от последней точки, а не то, что видно в начале строки.</p>`,

  ph_term: `<p><span class="yes">Верно:</span> <b>социальная инженерия</b> — получение доступа через человека, а не через код: подмена личности, лесть, авторитет, срочность.</p>`,

  ph_vishing: `<p><span class="yes">Верно:</span> <b>vishing</b> (voice + phishing) — фишинг по телефону: «служба безопасности банка» просит код из SMS или данные карты. Проверка та же, что и для писем: перезвонить по номеру с карты.</p>`,

  ph_spear: `<p><span class="yes">Верно:</span> <b>spear phishing</b> — целевой фишинг, «копьё»: письмо, подготовленное под конкретного человека (его роль, язык, проекты), поэтому выглядит убедительнее массовой рассылки.</p>`,
/* ---------- question: Windows ---------- */
  cmd_dir: `<p><span class="yes">Верно:</span> <code>dir</code> показывает содержимое каталога. Полезные ключи: <code>dir /a</code> — включая скрытые и системные, <code>dir *.log</code> — по маске.</p>`,

  cmd_type: `<p><span class="yes">Верно:</span> <code>type</code> выводит содержимое текстового файла (<code>type secret.txt</code>). Для больших файлов удобнее <code>more</code>.</p>`,

  cmd_clear: `<p><span class="yes">Верно:</span> <code>cls</code> очищает экран (в PowerShell — <code>clear</code>). В реальной работе то же делает <code>cls</code> в начале скрипта, чтобы вывод был читаемым.</p>`,

  cmd_findstr: `<p><span class="yes">Верно:</span> <code>findstr</code> ищет строки в файлах — аналог <code>grep</code>. Примеры: <code>findstr /S /I "error" *.log</code>, <code>findstr CYBER Documents\\system.log</code>.</p>`,

  cmd_redirect: `<p><span class="yes">Верно:</span> <code>&gt;</code> перенаправляет вывод с перезаписью файла (<code>ipconfig &gt; net.txt</code>), а <code>&gt;&gt;</code> дописывает. Осторожно: перезапись стирает прежние данные — для отчётов используйте <code>2&gt;&amp;1 |</code> или <code>Start-Transcript</code>.</p>`,

  ps_verb: `<p><span class="yes">Верно:</span> глагол <b>Get-</b> (читать данные). Благодаря шаблону «глагол-существительное» можно запоминать семейство: <code>Get-Service</code>, <code>Get-Process</code>, <code>Get-Content</code>.</p>`,

  ps_read_file: `<p><span class="yes">Верно:</span> <code>Get-Content</code> (алиас <code>gc</code>) читает файл. Полезно: <code>-Head</code>/<code>-Tail</code>, <code>-Wait</code> для логов в реальном времени.</p>`,

  ps_proc: `<p><span class="yes">Верно:</span> <code>Get-Process</code> (алиас <code>ps</code>) показывает процессы. Часто применяют фильтры: <code>Get-Process | Sort-Object CPU -Descending</code>.</p>`,

  ps_pipe: `<p><span class="yes">Верно:</span> <code>|</code> — конвейер: передаёт объекты от одного командлета к следующему. Именно так строятся цепочки вида <code>Get-Process | Where-Object CPU -gt 100 | Stop-Process</code>.</p>`,

  ps_verb_new: `<p><span class="yes">Верно:</span> глагол <b>New-</b> (создать объект): <code>New-Item</code>, <code>New-LocalUser</code>. Парный глагол <code>Set-</code> меняет существующий объект.</p>`,

  ps_log: `<p><span class="yes">Верно:</span> <b>Script Block Logging</b> — журналирование содержимого выполняемых скриптов PowerShell (Event ID 4104 в Security log). Это позволяет увидеть, что именно исполнялось, даже если команда была закодирована в base64.</p>`,

  wu_netuser: `<p><span class="yes">Верно:</span> <code>net user</code> перечисляет локальные учётки; <code>net user /domain</code> — доменные. Для деталей: <code>net user &lt;имя&gt;</code>, <code>net localgroup administrators</code>.</p>`,

  wu_uac: `<p><span class="yes">Верно:</span> <b>UAC</b> (User Account Control) — механизм, отделяющий стандартные операции от административных и запрашивающий подтверждение при повышении прав. Отключать его не стоит: это одна из базовых защит.</p>`,

  wu_icacls: `<p><span class="yes">Верно:</span> <code>icacls</code> показывает и меняет ACL файлов и папок (<code>icacls file.txt</code>, <code>icacls file.txt /grant user:F</code>). Проверять права нужно именно на сервере — скрытие кнопки в UI ничего не меняет.</p>`,

  wu_system: `<p><span class="yes">Верно:</span> <b>NT AUTHORITY\\SYSTEM</b> — встроенная учётка, права которой выше Administrator: она владеет most системными ресурсами и работает службами. Из-за этого замена исполняемого файла службы, запущенной от SYSTEM, даёт немедленное повышение привилегий.</p>`,

  wu_priv: `<p><span class="yes">Верно:</span> принцип <b>минимальных привилегий</b> (least privilege): учётке даётся ровно столько прав, сколько нужно для работы. Проверяется командой <code>whoami /priv</code>.</p>`,

  wr_systeminfo: `<p><span class="yes">Верно:</span> <code>systeminfo</code> показывает ОС, архитектуру, имя компьютера и список установленных патчей. Полезно при триаже: по версии ОС сразу понятно, какие обновления отсутствуют.</p>`,

  wr_tasklist: `<p><span class="yes">Верно:</span> <code>tasklist</code> показывает процессы. Детект-ориентир: незнакомые имена, несколько экземпляров системных процессов, процессы без описания, запущенные из Temp или Downloads.</p>`,

  wr_netstat: `<p><span class="yes">Верно:</span> <code>netstat</code> показывает активные соединения и слушающие порты (<code>netstat -ano</code> добавляет PID). Используется и для триажа (куда стучится процесс), и для проверки подозрительных исходящих соединений.</p>`,

  wr_priv: `<p><span class="yes">Верно:</span> <code>whoami /priv</code> показывает привилегии текущего пользователя. Полезно при разведке: видно, есть ли у процесса SeDebugPrivilege или SeImpersonatePrivilege — их используют для повышения прав.</p>`,

  wr_schtasks: `<p><span class="yes">Верно:</span> <code>schtasks</code> показывает запланированные задачи (<code>/query</code>) — одно из любимых мест закрепления вредоноса вместе с Run-ключами и службами.</p>`,

  /* ---------- question: Сети ---------- */
  tcp_https: `<p><span class="yes">Верно:</span> 443/tcp — стандартный порт HTTPS (HTTP поверх TLS). В реестре IANA он зарегистрирован как <code>https</code>.</p>`,

  tcp_ssh: `<p><span class="yes">Верно:</span> 22/tcp — SSH. Замена Telnet (23): шифрует канал и поддерживает ключи вместо паролей.</p>`,

  tcp_handshake: `<p><span class="yes">Верно:</span> первым клиент отправляет <b>SYN</b>, сервер отвечает SYN+ACK, клиент — ACK. Это и есть three-way handshake; SYN-скан (<code>-sS</code>) отправляет только SYN и не завершает соединение.</p>`,

  tcp_udp: `<p><span class="yes">Верно:</span> <b>UDP</b> работает без установления соединения — сообщения уходят сразу, без handshake. Отсюда DNS, VoIP и стриминг, и отсюда же сложность фильтрации и amplification-атаки.</p>`,

  tcp_layer: `<p><span class="yes">Верно:</span> IP работает на <b>третьем</b> уровне OSI (сетевом). Ниже — канальный и физический, выше — транспорт (TCP/UDP) и прикладной (HTTP, DNS).</p>`,

  nm_version: `<p><span class="yes">Верно:</span> <code>-sV</code> (service version detection) определяет версии сервисов. Скан заметен, поэтому на громоздких хостах его делают аккуратно и в рамках согласованного Scope.</p>`,

  nm_allports: `<p><span class="yes">Верно:</span> <code>-p-</code> означает «все порты» (1–65535). Если полный скан не нужен, быстрее и тише — <code>--top-ports 1000</code>.</p>`,

  nm_syn: `<p><span class="yes">Верно:</span> <code>-sS</code> — SYN-скан, «полуоткрытый»: соединение не завершается, поэтому не попадает в журналы приложений. Требует raw-сокетов (root или администратор).</p>`,

  nm_filtered: `<p><span class="yes">Верно:</span> <b>filtered</b> — порт не ответил или ответ отброшен межсетевым экраном. Для закрытого порта вывод был бы <code>closed</code>, и различие показывает, где стоит фильтр.</p>`,

  nm_os: `<p><span class="yes">Верно:</span> <code>-O</code> пытается определить ОС по сигнатурам стека TCP/IP. Метод неточен на современных системах и заметен администратору цели — надёжнее смотреть версии сервисов (<code>-sV</code>).</p>`,

  na_sniffer: `<p><span class="yes">Верно:</span> <b>Wireshark</b> — графический анализатор трафика. Перехват чужого трафика без разрешения — правонарушение, поэтому инструмент применяют только на своём или явно разрешённом трафике.</p>`,

  na_mitm: `<p><span class="yes">Верно:</span> <b>MITM</b> (Man-in-the-Middle) — атака «человек посередине»: перехват и подмена трафика между двумя сторонами. Защита — TLS с проверкой сертификата; в локалке — Dynamic ARP Inspection и port security.</p>`,

  na_arp: `<p><span class="yes">Верно:</span> <b>ARP</b> сопоставляет IP и MAC в локальной сети. Ответив ARP-подменой (ARP spoofing), атакующий становится шлюзом для жертвы. Защита — Dynamic ARP Inspection на коммутаторах и статические записи ARP.</p>`,

  /* ---------- question: Веб (OWASP) ---------- */
  ow_idor: `<p><span class="yes">Верно:</span> IDOR (Insecure Direct Object Reference) — доступ к чужому объекту подменой идентификатора в URL. Это A01:2025 Broken Access Control, самый частый реальный класс дыр в API.</p>`,

  ow_org: `<p><span class="yes">Верно:</span> OWASP — Open Worldwide Application Security Project, некоммерческое сообщество, публикующее Top 10 и другой гайдлайн (WSTG, ASVS, Cheat Sheet Series).</p>`,

  ow_first: `<p><span class="yes">Верно:</span> Broken Access Control — A01 и в редакции 2025, и в 2021, и в 2019. Причина лидерства проста: проверку прав на сервере забывают чаще всего.</p>`,

  ow_ssrf: `<p><span class="yes">Верно:</span> SSRF (Server-Side Request Forgery) — заставили сервер обратиться к внутреннему ресурсу от своего имени: metadata-сервис облака, внутренние API, 127.0.0.1. Защита — allow-list адресов и запрет перехода на link-local/metadata.</p>`,

  ow_cve: `<p><span class="yes">Верно:</span> CVE — публичный идентификатор уязвимости (например, CVE-2021-44228, Log4Shell). Нужен, чтобы все говорили об одном и том же баге; в связке с CVSS даёт приоритет исправлению.</p>`,

  sql_payload: `<p><span class="yes">Верно:</span> условие вида <code>1' OR '1'='1</code> закрывает кавычку, добавляет всегда-истинное условие и комментирует остаток запроса. В <code>WHERE name='' OR '1'='1'</code> возвращается первая строка — обычно admin.</p>
    <p>Почему это уязвимость: пользовательские данные склеиваются с кодом. Лечится не «фильтрацией кавычек», а параметризованными запросами, где данные передаются отдельно от кода.</p>`,

  sql_defense: `<p><span class="yes">Верно:</span> <b>prepared statements</b> (параметризованные запросы): SQL разбирается один раз, а значения подставляются как данные. Даже если в значении есть кавычка или <code>OR</code>, она остаётся строкой, а не кодом.</p>`,

  sql_union: `<p><span class="yes">Верно:</span> <b>UNION</b> приклеивает результат второго SELECT к первому, если число столбцов совпадает. Так из одной инъекции читают чужие таблицы: <code>' UNION SELECT username, password FROM users--</code>.</p>`,

  sql_blind: `<p><span class="yes">Верно:</span> <b>blind</b> — инъекция, при которой ответ не виден напрямую (например, страница возвращает только «верно/неверно»). Данные извлекают по биту за запрос: условные конструкции или по времени отклика.</p>`,

  xss_stored: `<p><span class="yes">Верно:</span> <b>stored</b> (сохраняемый) XSS: payload пишется в базу (комментарий, профиль) и срабатывает у всех, кто открывает страницу. Самый опасный тип — заражает каждого посетителя и может красть сессии всех.</p>`,

  xss_reflected: `<p><span class="yes">Верно:</span> <b>reflected</b> (отражаемый) XSS: код приходит в ссылке или параметре и отражается в ответе сервера. Не требует сохранения, но отлично работает в фишинговых ссылках и почте.</p>`,

  xss_csp: `<p><span class="yes">Верно:</span> <b>CSP</b> (Content Security Policy) — заголовок, ограничивающий, откуда браузер может брать скрипты и стили (<code>script-src 'self'</code>). Второй рубеж: не отменяет экранирование, но ломает даже забытый payload.</p>`,

  xss_cookie: `<p><span class="yes">Верно:</span> <b>HttpOnly</b> запрещает JavaScript доступ к cookie, поэтому украсть сессионный cookie через XSS нельзя. Пароль от самой cookie не защищает — его всё равно нужно отправлять.</p>`,

  wa_idor: `<p><span class="yes">Верно:</span> IDOR — доступ к объекту по идентификатору без проверки прав. Лечится проверкой на сервере: <code>if (obj.ownerId !== user.id) 403</code>, а не «скрытием» ссылки в интерфейсе.</p>`,

  wa_csrf: `<p><span class="yes">Верно:</span> <b>CSRF</b> (Cross-Site Request Forgery) — атака, при которой браузет жертвы отправляет авторизованный запрос на сайт, где она залогинена, потому что атакующая страница просто содержит форму или скрипт.</p>`,

  wa_token: `<p><span class="yes">Верно:</span> <b>CSRF-токен</b> — непредсказуемое случайное значение в форме; сервер сверяет его с тем, что хранит в сессии. Чужой сайт не может его прочитать, поэтому запрос отсекается.</p>`,

  wa_samesite: `<p><span class="yes">Верно:</span> атрибут <b>SameSite</b> запрещает браузеру отправлять cookie в межсайтовые запросы (<code>Lax</code> — по клику из внешней ссылки, <code>Strict</code> — никогда). Это самая простая защита от CSRF-форм.</p>`,

  /* ---------- question: Пентестинг ---------- */
  eth_scope: `<p><span class="yes">Верно:</span> <b>Scope</b> — согласованные границы теста: какие системы, адреса, окна времени и техники разрешены. Всё за пределами Scope — запрещено, даже если «выглядит безобидно».</p>`,

  eth_roe: `<p><span class="yes">Верно:</span> <b>RoE</b> (Rules of Engagement) — правила поведения: разрешённые техники, точки контакта, эскалация, что делать при инциденте и как хранить данные. Это то, что подписывают до начала работ.</p>`,

  eth_blackbox: `<p><span class="yes">Верно:</span> <b>black box</b> — тест без предварительного знания о системе: только внешне наблюдаемое поведение. Противоположности: white box (доступ к коду) и grey box (частичное знание, например учётные данные).</p>`,

  eth_bounty: `<p><span class="yes">Верно:</span> <b>bug bounty</b> — программа, где компания публично обещает вознаграждение за найденные и переданные по правилам уязвимости. Проверять нужно сами правила программы: что считается дырой, а что — нет.</p>`,

  meth_first: `<p><span class="yes">Верно:</span> <b>reconnaissance</b> (разведка) — сбор информации о цели без активного воздействия: домены, сотрудники, технологии, открытые репозитории. Результат определяет, куда смотреть дальше.</p>`,

  meth_last: `<p><span class="yes">Верно:</span> <b>reporting</b> (отчёт) — фаза, которая даёт заказчику ценность: что найдено, каков риск, что делать и в каком порядке. Без отчёта тест не имеет смысла для бизнеса.</p>`,

  meth_privesc: `<p><span class="yes">Верно:</span> <b>privesc</b> (privilege escalation) — повышение привилегий: с обычного пользователя до администратора, с пользователя домена до доменного админа, с сервисной учётки до SYSTEM.</p>`,

  meth_lateral: `<p><span class="yes">Верно:</span> <b>lateral movement</b> — переход на соседние машины внутри сети после первого foothold. Обычно через учётные данные в памяти, SMB, RDP, Kerberos и доверие между узлами.</p>`,

  meth_attack: `<p><span class="yes">Верно:</span> <b>ATT&amp;CK</b> — база знаний MITRE о тактиках и техниках реальных атак. Нужна и атакующему (сценарии), и защитнику (покрытие detections и hunting).</p>`,

  rp_passive: `<p><span class="yes">Верно:</span> <b>пассивная</b> разведка — работа только с открытыми источниками: WHOIS, DNS, GitHub, вакансии, соцсети, кэш поисковиков. Цель не замечает вас вообще.</p>`,

  rp_dork: `<p><span class="yes">Верно:</span> <b>google dork</b> — поиск с операторами (<code>site:</code>, <code>filetype:</code>, <code>inurl:</code>) для поиска утечек: открытых ключей, конфигов, баз, панелей. Пассивно, но результат может быть очень чувствительным.</p>`,

  rp_whois: `<p><span class="yes">Верно:</span> <b>whois</b> показывает владельца домена, контакты, даты регистрации и историю изменений (домен зарегистрирован вчера — повод насторожиться).</p>`,

  rp_dns: `<p><span class="yes">Верно:</span> <b>MX</b>-записи указывают почтовые серверы домена; дополнительно полезны TXT (SPF/DKIM, проверка домена на email-сервисы), NS и CNAME (какие сервисы используются).</p>`,

  pte_msf: `<p><span class="yes">Верно:</span> <b>Metasploit</b> — фреймворк для эксплуатации: содержит модули, полезные нагрузки, Meterpreter и пост-эксплуатацию. Используется и для проверки гипотез в лаборатории, легально.</p>`,

  pte_burp: `<p><span class="yes">Верно:</span> <b>Burp Suite</b> — прокси для перехвата и ручного тестирования веб-трафика: перехват запросов, повторение, фаззинг, анализ уязвимостей.</p>`,

  pte_cvss: `<p><span class="yes">Верно:</span> <b>CVSS</b> (Common Vulnerability Scoring System) — шкала 0–10, учитывающая вектор атаки, сложность, требуемые привилегии и влияние на конфиденциальность, целостность и доступность. Позволяет одинаково сравнивать находки разных типов.</p>`,

  /* ---------- question: Криптография ---------- */
  enc_reversible: `<p><span class="yes">Верно:</span> Base64 — <b>кодирование</b>: обратное преобразование возможно без ключа, потому что это просто перевод байтов в символы. Шифрование требует ключа и алгоритма, недоступных без него.</p>`,

  enc_hex: `<p><span class="yes">Верно:</span> <b>hex</b> (шестнадцатеричная запись) — каждый байт кодируется двумя символами 0–9 и a–f. Читаемый глазом, удобен для ключей и хешей, но защиты не даёт.</p>`,

  enc_sign: `<p><span class="yes">Верно:</span> <b>=</b> — паддинг: длина Base64 кратна 4, поэтому неполный блок дополняется знаками равенства. Встречается в конце закодированных строк и паролей.</p>`,

  hash_salt: `<p><span class="yes">Верно:</span> <b>соль</b> — случайная уникальная строка перед хешированием. Одинаковые пароли дают разные хеши, а готовые радужные таблицы перестают подходить.</p>`,

  hash_pw: `<p><span class="yes">Верно:</span> <b>bcrypt</b> (а также argon2, scrypt) — медленные хеш-функции, специально сделанные дорогими: перебор в тысячи раз дороже, чем у SHA-256, и у каждого пароля своя соль.</p>`,

  hash_len256: `<p><span class="yes">Верно:</span> у SHA-256 выход <b>256 бит</b> (32 байта, 64 hex-символа). Коллизии при таком размере считаются практически невозможными.</p>`,

  hash_collision: `<p><span class="yes">Верно:</span> <b>коллизия</b> — два разных входа дают один и тот же хеш. Именно это и сломало MD5 и SHA-1: подделанный сертификат с тем же хешем, как у доверенного.</p>`,

  hash_hmac: `<p><span class="yes">Верно:</span> <b>HMAC</b> — хеш с секретным ключом: <code>H(key || message)</code>. Без ключа подделать нельзя, поэтому HMAC доказывает и целостность, и подлинность источника.</p>`,

  asym_aes: `<p><span class="yes">Верно:</span> <b>AES</b> (Advanced Encryption Standard) — симметричный стандарт, утверждённый NIST в 2001 году, с ключами 128/192/256 бит. Скорость и поддержка в железе делают его выбором по умолчанию.</p>`,

  asym_pub: `<p><span class="yes">Верно:</span> шифрование выполняется <b>публичным</b> ключом, расшифровка — приватным. Это и делает возможным безопасный обмен: получить открытый ключ может кто угодно.</p>`,

  asym_priv: `<p><span class="yes">Верно:</span> расшифровывает <b>приватный</b> (закрытый) ключ владельца. Пока он секретен, никто другой прочитать данные не сможет.</p>`,

  asym_rsa: `<p><span class="yes">Верно:</span> <b>RSA</b> — классическая асимметричная схема на математике больших чисел. Используется для подписей и обмена ключами; шифрование больших объёмов данных ею неэффективно, поэтому данные шифруют AES.</p>`,

  ct_sign: `<p><span class="yes">Верно:</span> подпись создаётся <b>приватным</b> ключом. Это доказывает авторство: публичный ключ может проверить подпись, но подделать её без закрытого нельзя.</p>`,

  ct_verify: `<p><span class="yes">Верно:</span> подпись проверяется <b>публичным</b> ключом. Публичность здесь безопасно: проверка не раскрывает секрет подписи и не позволяет ею злоупотребить.</p>`,

  ct_ca: `<p><span class="yes">Верно:</span> <b>CA</b> (Certificate Authority) — удостоверяющий центр, который выпускает и подписывает сертификаты, проверяя домен и компанию. Отпечатки корневых CA зашиты в браузеры и ОС.</p>`,

  ct_pki: `<p><span class="yes">Верно:</span> <b>PKI</b> (Public Key Infrastructure) — вся система: сертификаты, удостоверяющие центры, цепочки доверия, отзыв (CRL/OCSP) и политики. HTTPS, подпись кода и VPN на сертификатах работают поверх неё.</p>`,

  /* ---------- question: OSINT ---------- */
  os_abbr: `<p><span class="yes">Верно:</span> OSINT = <b>Open Source Intelligence</b>, «разведка по открытым источникам». Отличается от конкурентной разведки ( HUMINT, SIGINT ) тем, что работает только с публичными и законно доступными данными.</p>`,

  os_exif: `<p><span class="yes">Верно:</span> <b>EXIF</b> — метаданные в фотографиях: модель и серийник камеры, дата, геометки, иногда GPS высота. Публикуются вместе с файлом, даже если сама картинка «ничего не выдаёт».</p>`,

  os_archive: `<p><span class="yes">Верно:</span> <b>Wayback Machine</b> (Internet Archive) хранит копии страниц по датам. Помогает и разведке (исторические домены, email в старых страницах), и расследованию утечек.</p>`,

  os_hibp: `<p><span class="yes">Верно:</span> <b>HIBP</b> (Have I Been Pwned) проверяет, встречался ли email в известных утечках. Используют и для своих адресов — так компании узнают о компрометации раньше злоумышленников.</p>`,

  so_site: `<p><span class="yes">Верно:</span> оператор <code>site:</code> ограничивает выдачу доменом: <code>site:example.com filetype:pdf</code>. В связке с <code>-</code> и кавычками позволяет точечно искать утечки.</p>`,

  so_filetype: `<p><span class="yes">Верно:</span> <code>filetype:</code> ищет по типу файла: <code>filetype:xlsx</code>, <code>filetype:sql</code>, <code>filetype:env</code>. Классика OSINT: забытые бэкапы баз и конфиги с ключами.</p>`,

  so_intitle: `<p><span class="yes">Верно:</span> <code>intitle:</code> ищет слово в заголовке — удобно для открытых листингов каталогов (<code>intitle:"index of"</code>), панелей и документов с внутренними названиями.</p>`,

  so_shodan: `<p><span class="yes">Верно:</span> <b>Shodan</b> индексирует открытые устройства и сервисы интернета с баннеров: можно найти камеры, RDP, оставленные тестовые панели. Ответственность за проверку остаётся на тестирующем.</p>`,

  op_username: `<p><span class="yes">Верно:</span> <b>username enumeration</b> — проверка, где один и тот же ник встречается: соцсети, форумы, маркетплейсы, репозитории. Связанные аккаунты дают атакующему список возможных email и интересов жертвы.</p>`,

  op_reverse: `<p><span class="yes">Верно:</span> <b>reverse image search</b> (поиск по изображению) находит, где картинка уже встречалась: другие версии, страницы с исходным фото, чужие аккаунты.</p>`,

  op_chrono: `<p><span class="yes">Верно:</span> <b>хронолокация</b> (geolocation по времени съёмки) — определение места по теням, погоде, видимым вывескам и событиям. Часто сужает круг поиска до конкретного района.</p>`,

  /* ---------- question: Active Directory ---------- */
  ad_dc: `<p><span class="yes">Верно:</span> <b>Domain Controller</b> хранит базу Active Directory (NTDS.dit) и обслуживает аутентификацию: без контроллера домен в сети не работает. Отсюда он — главная цель и самое критичное место резервного копирования.</p>`,

  ad_kerb: `<p><span class="yes">Верно:</span> <b>Kerberos</b> — основной протокол аутентификации домена: TGT выдаётся при входе, затем используется для доступа к сервисам (TGS). NTLM остаётся как fallback и сам по себе уязвим.</p>`,

  ad_ldap: `<p><span class="yes">Верно:</span> <b>LDAP</b> (Lightweight Directory Access Protocol) — протокол запросов к каталогу: перечисление пользователей, групп, компьютеров. Kerberos аутентифицирует, LDAP отдаёт данные каталога.</p>`,

  ad_tgt: `<p><span class="yes">Верно:</span> <b>TGT</b> (Ticket Granting Ticket) выдаётся KDC при входе и используется как «пропуск» для получения билетов на сервисы. Его кража из памяти или из кеша — типичный шаг атаки.</p>`,

  ad_forest: `<p><span class="yes">Верно:</span> <b>лес</b> — верхний уровень структуры AD: несколько доменов с общей схемой, конфигурацией и глобальным каталогом. Домен внутри леса — единица безопасности и политик.</p>`,

  ad_gpo: `<p><span class="yes">Верно:</span> <b>GPO</b> (Group Policy Object) — объект групповой политики: правила для пользователей и компьютеров в домене/OU. Через GPO можно развернуть и настройки безопасности, и малварь при доменных правах.</p>`,

  adr_users: `<p><span class="yes">Верно:</span> <code>net user /domain</code> показывает пользователей домена. Локальный вариант — просто <code>net user</code>. Всё это — легальная разведка в рамках согласованного Scope.</p>`,

  adr_kerb: `<p><span class="yes">Верно:</span> <b>Kerberoasting</b>: запрашивают билет сервисной учётки с SPN и перебирают её пароль офлайн. Особенно эффективно, потому что доменные политики паролей обычно слабее локальных.</p>`,

  adr_bh: `<p><span class="yes">Верно:</span> <b>BloodHound</b> строит граф «пользователь → группа → сессия → компьютер» и показывает кратчайшие пути к Domain Admin. Инструмент используют и для атаки (поиск пути), и для защиты (сокращение путей).</p>`,

  adr_spn: `<p><span class="yes">Верно:</span> наличие <b>SPN</b> (Service Principal Name) делает учётку «кераберостой»: её можно использовать вместо пользователя, а её хеш — добыть по запросу TGS.</p>`,

  add_laps: `<p><span class="yes">Верно:</span> <b>LAPS</b> (Local Administrator Password Solution) даёт каждому администратору уникальный случайный пароль на каждый компьютер. Устраняет общий пароль админа, с которым можно захватить всю сеть.</p>`,

  add_pth: `<p><span class="yes">Верно:</span> <b>pass-the-hash</b> — атака, при которой похищенный NTLM-хеш подставляется вместо пароля. Пароль при этом не знают, поэтому 2FA с паролем не спасает. Защита: LAPS, Credential Guard, отключение NTLM.</p>`,

  add_admins: `<p><span class="yes">Верно:</span> группа <b>Domain Admins</b> — владеет всем доменом: любой её участник может стать владельцем любого объекта AD, включая контроллер домена.</p>`,

  add_tier: `<p><span class="yes">Верно:</span> <b>Tier 0</b> — контроллеры домена, администраторы домена и агентства безопасности. Модель tiering (Tier 0 / 1 / 2) нужна, чтобы админы обычных серверов не могли администрировать Tier 0.</p>`,

  /* ---------- question: Реверс-инжиниринг ---------- */
  re_pe: `<p><span class="yes">Верно:</span> <b>PE</b> (Portable Executable) — формат исполняемых файлов Windows (.exe, .dll, .sys). Его структура — DOS-заголовок, PE-заголовок, секции, таблица импорта — то, что читает любой анализатор.</p>`,

  re_static: `<p><span class="yes">Верно:</span> <b>статический</b> анализ — исследование без запуска: дизассемблирование, строки, хеши, заголовки. Безопасно для окружения, но упакованный код покажет только обёртку.</p>`,

  re_tool: `<p><span class="yes">Верно:</span> <b>Ghidra</b> (NSA, открытая) и <b>IDA Pro</b> (коммерческая) — дизассемблеры; <code>x64dbg</code> и <code>radare2</code> — отладчики/анализаторы для динамики.</p>`,

  re_iat: `<p><span class="yes">Верно:</span> <b>IAT</b> (Import Address Table) — список функций, которые программа импортирует из DLL: <code>CreateRemoteThread</code>, <code>VirtualAllocEx</code>, <code>WriteProcessMemory</code> сразу подсказывают назначение. Упаковщики скрывают её распаковкой во время выполнения.</p>`,

  re_mz: `<p><span class="yes">Верно:</span> PE-файл начинается с сигнатуры <b>MZ</b> (0x4D5A, от DOS), а адрес PE-заголовка лежит по смещению <code>e_lfanew</code>. Проверка «MZ…PE» — первый фильтр: исполняемый формат должен иметь обе подписи.</p>`,

  res_tool: `<p><span class="yes">Верно:</span> <b>strings</b> извлекает печатаемые последовательности из бинаря: домены C2, пути, ключи реестра, сообщения об ошибках. Часто это самая быстрая находка при анализе малвари.</p>`,

  res_ioc: `<p><span class="yes">Верно:</span> <b>IOC</b> (Indicator of Compromise) — наблюдаемый признак взлома: хеш файла, IP или домен C2, ключ реестра, имя мутекса. Найденный IOC проверяют, а не публикуют «как есть» — иначе он бесполезен.</p>`,

  rea_pack: `<p><span class="yes">Верно:</span> <b>упаковка</b> (packing): код сжимается или шифруется и распаковывается в памяти при запуске. Признаки — высокое значение энтропии, мало строк, импорты вида <code>VirtualAlloc</code>/<code>WriteProcessMemory</code>.</p>`,

  rea_dbg: `<p><span class="yes">Верно:</span> <b>IsDebuggerPresent</b> — WinAPI-функция, читающая флаг в PEB: у отлаживаемого процесса он установлен, и малварь меняет поведение (засыпает, завершается, выдаёт мусор).</p>`,

  rea_upx: `<p><span class="yes">Верно:</span> <b>UPX</b> — самый известный открытый упаковщик PE. Используется не только для защиты, но и для упаковки вредоносов, поэтому наличие секций <code>UPX0/UPX1</code> — повод насторожиться.</p>`,

  /* ---------- question: Цифровая форензика ---------- */
  fo_integrity: `<p><span class="yes">Верно:</span> <b>хеш</b> (SHA-256 и выше). Хеш образа фиксируется сразу после снятия копии и повторяется перед анализом: несовпадение означает, что улика менялась.</p>`,

  fo_coc: `<p><span class="yes">Верно:</span> <b>Chain of Custody</b> (цепь владения) — документированная история обращения с уликой: кто, когда, как получил, хранил и передавал. Именно она превращает технические улики в допустимые доказательства.</p>`,

  fo_vol: `<p><span class="yes">Верно:</span> <b>RAM</b> собирают первыми (порядок волатильности из NIST SP 800-61): содержимое памяти исчезает при обесточивании — вместе с ключами, сессиями и бесфайловым вредоносом.</p>`,

  fo_wb: `<p><span class="yes">Верно:</span> <b>write blocker</b> — аппаратный или программный блокиратор записи, который физически блокирует каналы записи при подключении диска к рабочей станции. Гарантирует, что оригинал не изменится.</p>`,

  foa_evtx: `<p><span class="yes">Верно:</span> журналы Windows лежат в файлах <code>.evtx</code> (<code>Security</code>, <code>System</code>, <code>PowerShell Operational</code>) в каталоге <code>%SystemRoot%\System32\winevt\Logs</code>.</p>`,

  foa_mft: `<p><span class="yes">Верно:</span> <b>MFT</b> (Master File Table) — главная база NTFS: по ней можно восстановить имена, размеры, временные метки (создания, изменения, доступа) иDeleted-файлы даже без содержимого.</p>`,

  foa_prefetch: `<p><span class="yes">Верно:</span> <b>Prefetch</b> хранит, какие программы запускались, сколько раз и когда (<code>Windows\Prefetch</code>). Для малвари особенно ценен факт запуска исполняемого файла из необычной папки.</p>`,

  foa_1102: `<p><span class="yes">Верно:</span> событие <b>1102</b> — «журнал безопасности очищен». В расследовании это улика само по себе: легитимный администратор чистит журналы только по процедуре, и факт стирания фиксируется в других журналах.</p>`,

  fom_vol: `<p><span class="yes">Верно:</span> <b>Volatility</b> — фреймворк анализа дампов памяти: извлекает процессы, сети, модули ядра, инъекции и артефакты без повторного запуска системы.</p>`,

  fom_fileless: `<p><span class="yes">Верно:</span> <b>fileless</b> — вредонос, работающий только в памяти (PowerShell, загрузка DLL, «безфайловые» техники). На диске остаются только следы в логах и артефакты PowerShell.</p>`,

  fom_pslist: `<p><span class="yes">Верно:</span> плагин <b>pslist</b> перечисляет процессы из дампа. Полезные дополнения: <code>pstree</code> (родители), <code>psscan</code> (поиск скрытых процессов), <code>cmdline</code> (аргументы).</p>`,

  /* ---------- question: Анализ фишинга ---------- */
  pha_spear: `<p><span class="yes">Верно:</span> <b>spear phishing</b> — целевое письмо под конкретного человека: используются его роль, язык, текущие проекты и коллеги. Поэтому в персонализированном фишинге работают подпись начальника и «продолжение» реальной переписки.</p>`,

  pha_whaling: `<p><span class="yes">Верно:</span> <b>whaling</b> — фишинг на топ-менеджмент (CEO, CFO). Цель — не «взлом почты», а крупная сумма: поддельный счёт, перенаправление выплаты, что требует иной защиты (подтверждение платежей по второму каналу).</p>`,

  pha_bec: `<p><span class="yes">Верно:</span> <b>BEC</b> (Business Email Compromise) — компрометация деловой переписки: подмена реквизитов, «новый» счёт поставщика, срочная просьба перевести деньги. Ущерб рекордный, потому что «всё легитимно» с точки зрения почты.</p>
    <p>Защита — верификация смены реквизитов по второму каналу и лимиты/двойное подтверждение платежей.</p>`,

  pha_attach: `<p><span class="yes">Верно:</span> <b>макросы</b> в документах Office (docm, xlsm, pptm) выполняют код при открытии файла. Классический почтовый этап малвари: «счёт» или «резюме» с макросом, который тянет payload.</p>
    <p>Современная защита: макросы по умолчанию отключены, файлы из интернета открываются в защищённом режиме, подписи кода.</p>`,

  pau_spf: `<p><span class="yes">Верно:</span> <b>SPF</b> — DNS-запись со списком серверов, которым разрешено слать почту от домена. Проверяет <i>конверт</i> (MAIL FROM), а не видимый From, поэтому подделать отправителя им нельзя, но спрятать реальный домен — можно.</p>`,

  pau_dkim: `<p><span class="yes">Верно:</span> <b>DKIM</b> — криптографическая подпись письма приватным ключом домена. Получатель проверяет её публичным ключом и убеждается, что содержимое не меняли в пути и отправитель действительно владеет доменом.</p>`,

  pau_dmarc: `<p><span class="yes">Верно:</span> <b>DMARC</b> объединяет результаты SPF и DKIM, добавляет проверку alignment (совпадение домена видимого From с прошедшим проверку) и задаёт политику: <code>none</code> / <code>quarantine</code> / <code>reject</code> плюс агрегированные отчёты.</p>`,

  pau_reject: `<p><span class="yes">Верно:</span> самый строгий режим — <code>p=reject</code>: почта не проходит DMARC вообще. <code>p=quarantine</code> отправляет её в спам, <code>p=none</code> только собирает отчёты. Переход к reject делают поэтапно, сначала <code>p=none</code>.</p>`,

  phh_ar: `<p><span class="yes">Верно:</span> заголовок <b>Authentication-Results</b> содержит вердикты mail-сервера: <code>spf=pass</code>, <code>dkim=pass</code>, <code>dmarc=pass</code> или <code>fail</code> с пояснением. Первый заголовок, который смотрит аналитик.</p>`,

  phh_mismatch: `<p><span class="yes">Верно:</span> расхождение <b>Return-Path</b> (реальный конвертный отправитель) с видимым <b>From</b> — классический признак спуфинга. При легитимной рассылке они совпадают (кроме служебных случаев вроде отписок).</p>`,

  phh_received: `<p><span class="yes">Верно:</span> цепочка <b>Received</b> показывает путь письма по серверам и IP отправителя. Читается снизу вверх: последняя строка ближе всего к вам, первая — у истока.</p>`,

  /* ---------- question: Харденинг ---------- */
  hdp_cis: `<p><span class="yes">Верно:</span> <b>CIS</b> (Center for Internet Security) выпускает Benchmarks — детальные списки безопасных настроек для Windows, Linux, сетевого оборудования и облаков. CIS Controls — отдельный набор высокоуровневых мер.</p>`,

  hdp_priv: `<p><span class="yes">Верно:</span> <b>least privilege</b> — учётке выдают минимум прав, необходимый для её работы. Проверяется на практике: права на файлы и службы, членство в группах, привилегии процесса.</p>`,

  hdp_level: `<p><span class="yes">Верно:</span> <b>Level 1</b> — базовый профиль: настройки без потери функциональности, применяется к большинству систем. <b>Level 2</b> — усиленный (для высоких рисков), может ломать часть приложений.</p>`,

  hdp_asr: `<p><span class="yes">Верно:</span> сокращение поверхности атаки: выключено лишнее, удалены неиспользуемые службы и порты, запрещены опасные макросы и скрипты. В Windows это в том числе правила <b>ASR</b> (Attack Surface Reduction) в Defender.</p>`,

  hdw_smb: `<p><span class="yes">Верно:</span> <b>SMBv1</b> — устаревшая версия протокола, через которую работал эксплойт WannaCry (вектор — EternalBlue). Отключается через SMB signing и удаление старых драйверов; SMBv2/3 остаются включёнными.</p>`,

  hdw_bitlocker: `<p><span class="yes">Верно:</span> <b>BitLocker</b> — штатное шифрование дисков Windows (и мобильных устройств). Без него украденный ноутбук превращается в источник всех секретов пользователя.</p>`,

  hdw_applock: `<p><span class="yes">Верно:</span> <b>AppLocker</b> и его современный преемник <b>WDAC</b> (Windows Defender Application Control) разрешают запуск только разрешённых приложений и скриптов. Мощнее «антивируса»: незнакомый бинарь просто не запустится.</p>`,

  hdw_whitelist: `<p><span class="yes">Верно:</span> подход <b>allowlisting</b> (whitelist) — разрешено только то, что явно перечислено, всё остальное запрещено. Обратная логика (blocklist) всегда оставляет лазейки для новых угроз.</p>`,

  hdb_patch: `<p><span class="yes">Верно:</span> <b>patch management</b> — управление обновлениями: тестирование, приоритизация (CVSS, критичность), окна обслуживания и контроль факта установки. Без процесса «слепые» патчи не доходят до машин.</p>`,

  hdb_drift: `<p><span class="yes">Верно:</span> <b>configuration drift</b> — расхождение реальной конфигурации с эталоном: кто-то поменял настройку «под себя», и через полгода никто не помнит зачем. Показывают drift-инструменты и сравнение с baseline.</p>`,

  hdb_baseline: `<p><span class="yes">Верно:</span> <b>security baseline</b> — эталонный набор безопасных настроек (например, из CIS Benchmark), с которым сравнивают реальные системы. Без базовой линии «правильно настроено» — понятие субъективное.</p>`,

  /* ---------- question: Blue Team ---------- */
  bts_siem: `<p><span class="yes">Верно:</span> <b>SIEM</b> — система, которая собирает логи, нормализует и коррелирует события и поднимает алерты по правилам. Смысл — увидеть атаку, размазанную по сотням хостов.</p>`,

  bts_edr: `<p><span class="yes">Верно:</span> <b>EDR</b> — телеметрия и реагирование на конечных точках: процессы, сети, реестр, поведение, изоляция хоста. Отличие от антивируса — реакция на поведение и возможность удалённо изолировать и расследовать.</p>`,

  bts_ioc: `<p><span class="yes">Верно:</span> <b>IOC</b> (Indicator of Compromise) — конкретный признак: хеш, IP, домен, имя файла. Хорош для обнаружения известного, плох для новых атак — поэтому нужны ещё IOA и поведенческие правила.</p>`,

  bts_l1: `<p><span class="yes">Верно:</span> <b>L1</b> — первый уровень SOC: первичный триаж, проверка алерта по инструкции, эскалация на L2/L3. Чем лучше L1 отсеивает шум, тем дороже анализ не дойдёт до старших уровней.</p>`,

  bts_hunt: `<p><span class="yes">Верно:</span> <b>threat hunting</b> — проактивный поиск угроз, по которым не пришло ни одного алерта: гипотезы, запросы к телеметрии, охота по MITRE ATT&amp;CK. Это то, где находят пропущенные вторжения.</p>`,

  bti_std: `<p><span class="yes">Верно:</span> <b>NIST SP 800-61</b> — стандарт реагирования на инциденты. Rev. 2 (2012) даёт четыре фазы, которые вы разбирали; Rev. 3 (апрель 2025) переводит рекомендации в термины NIST CSF 2.0.</p>`,

  bti_contain: `<p><span class="yes">Верно:</span> <b>containment</b> (сдерживание) — короткосрочная мера, останавливающая распространение: изоляция хоста от сети, блокировка аккаунта, отзыв токенов. Сначала локализуем, потом лечим.</p>`,

  bti_first: `<p><span class="yes">Верно:</span> <b>подготовка</b> (Preparation) выполняется до инцидента: роли, контакты, playbook-и, доступ к системам, учётные данные для реагирования. Без неё фаза реагирования превращается в хаос.</p>`,

  bta_tactics: `<p><span class="yes">Верно:</span> <b>14</b> тактик в матрице MITRE ATT&amp;CK для Enterprise: Reconnaissance, Resource Development, Initial Access, Execution, Persistence, Privilege Escalation, Defense Evasion, Credential Access, Discovery, Lateral Movement, Collection, Command and Control, Exfiltration, Impact.</p>`,

  bta_ttp: `<p><span class="yes">Верно:</span> вершина Pyramid of Pain — <b>TTP</b> (Tactics, Techniques, Procedures): поведение атакующего. Хеш меняется пересборкой, домен — регистрацией, а вот способ работы остаётся узнаваемым.</p>`,

  bta_author: `<p><span class="yes">Верно:</span> автор Pyramid of Pain — Дэвид Бьянко (David Bianco). Модель появилась в 2013 году и быстро стала способом объяснить, почему «просто добавить индикатор» недостаточно.</p>`,

  /* ---------- question: Анализ вредоносов ---------- */
  mwt_static: `<p><span class="yes">Верно:</span> <b>статический</b> анализ — разбор файла без запуска: хеш, тип файла, строки, PE-структура, подпись, упаковка. Безопасно и быстро, но поведение не видно.</p>`,

  mwt_dynamic: `<p><span class="yes">Верно:</span> <b>динамический</b> анализ — запуск в изолированной среде (вредонастка, VM с outbound-блоком) с наблюдением за поведением: файлы, реестр, процессы, сеть. Даёт то, чего не видно статикой.</p>`,

  mwt_worm: `<p><span class="yes">Верно:</span> <b>worm</b> (червь) распространяется сам по сети, сканируя уязвимые узлы и заражая их без участия пользователя. Пример — WannaCry. Отличие от вируса — сетевой вектор вместо файлов и носителей.</p>`,

  mwt_rat: `<p><span class="yes">Верно:</span> <b>RAT</b> (Remote Access Trojan) — троян с полноценным удалённым управлением: клавиатура, экран, файлы, выполнение команд. Заметная активность в памяти и длинные сессии C2.</p>`,

  mwl_snapshot: `<p><span class="yes">Верно:</span> <b>snapshot</b> (снимок) — точка отката состояния VM. Позволяет анализировать очередной образец с чистого состояния: без накопленных артефактов от предыдущих запусков.</p>`,

  mwl_vt: `<p><span class="yes">Верно:</span> <b>VirusTotal</b> — сервис, где файл проверяют десятки антивирусов и можно посмотреть метки других аналитиков. Удобен для проверки легитимности файла, опасен для конфиденциальных образцов.</p>`,

  mwl_hash: `<p><span class="yes">Верно:</span> <b>хеш</b> (обычно SHA-256) — однозначный идентификатор образца. По нему образец связывают с прошлыми инцидентами и базами IOC: один и тот же файл узнаётся мгновенно.</p>`,

  mwl_inetsim: `<p><span class="yes">Верно:</span> <b>INetSim</b> и аналоги (<code>Fakenet-NG</code>) эмулируют сетевые сервисы: ответы на DNS, HTTP и «ничего не делающую» реальную сеть. Так вы видите, куда малварь стучится, не выпуская его наружу.</p>`,

  mwb_persist: `<p><span class="yes">Верно:</span> закрепление (<i>persistence</i>) — механизм автозапуска: ключи <code>Run</code>/<code>RunOnce</code>, задачи планировщика, службы, WMI-подписки, модифицированные ярлыки. Ищите это первым при разборе хоста.</p>`,

  mwb_c2: `<p><span class="yes">Верно:</span> <b>C2</b> (Command and Control) — канал связи с оператором. Признаки: редкие обращения к неизвестному IP или домену, TLS к странным хостам, DNS-запросы с высокой энтропией, постоянный поток на один адрес.</p>`,

  mwb_beacon: `<p><span class="yes">Верно:</span> <b>beacon</b> — характерная периодичность обращений к C2 (например, каждые 60 секунд с небольшим jitter). Сама по себе периодичность — сильный индикатор: легальный трафик так не выглядит.</p>`,

  mwb_inject: `<p><span class="yes">Верно:</span> инъекция кода (<i>process injection</i>) — внедрение своего кода в чужой процесс, чтобы выполняться под его именем и правами (и пережить завершение исходного бинаря). Признаки видны в дампе памяти: <code>malfind</code>, аномальные регионы RWX.</p>
    <p>Разновидности: process hollowing, reflective DLL, APC injection, атака через подсистему PowerShell.</p>`,

  /* ---------- Дополнения (задания, добавленные позже) ---------- */
  na_dns: `<p><span class="yes">Верно:</span> подмена ответов <b>DNS</b> (spoofing, cache poisoning) уводит жертву на поддельный сайт по «правильному» имени. Защита — DNSSEC, шифрование DNS (DoH/DoT) и проверка сертификата в браузере.</p>`,

  wa_secure: `<p><span class="yes">Верно:</span> флаг <b>Secure</b> разрешает передавать cookie только по HTTPS. Без него cookie утечёт в открытом Wi-Fi при обычном HTTP-запросе к тому же домену.</p>`,

  pte_cve: `<p><span class="yes">Верно:</span> <b>CVE</b> — публичный идентификатор уязвимости вида <code>CVE-2021-44228</code>. В отчёте он превращает «у нас дыра» в конкретную, проверяемую проблему с вендором.</p>`,

  ct_tls: `<p><span class="yes">Верно:</span> <b>TLS</b> пришёл на смену устаревшему SSL. Сейчас используются только TLS 1.2/1.3, а SSL 2/3 и TLS 1.0/1.1 считаются небезопасными.</p>`,

  so_hibp: `<p><span class="yes">Верно:</span> <b>HIBP</b> — сервис проверки своего email по базам утечек. В связке с пониманием, что это проверка <i>своего</i> адреса, а не чужих, — простой способ узнать о компрометации заранее.</p>`,

  op_puppet: `<p><span class="yes">Верно:</span> <b>sock puppet</b> — отдельный аккаунт, не связанный с личностью исследователя: позволяет наблюдать площадку, не раскрывая себя и не смешивая личные данные с рабочими.</p>`,

  add_event: `<p><span class="yes">Верно:</span> событие <b>4769</b> — «выдан билет сервиса» (TGS). Всплеск 4769 с нетипичной частотой или с необычными SPN — признак Kerberoasting; рядом стоит искать 4624 (входы) и 4662 (доступ к объектам AD).</p>`,

  rea_entropy: `<p><span class="yes">Верно:</span> <b>энтропия</b> — мера случайности байтов. Высокая (около 8 из 8) означает шифрование, сжатие или упаковку; низкая — читаемый код или данные. Дешёвый первый фильтр при потоковом анализе.</p>`,

  fom_malfind: `<p><span class="yes">Верно:</span> <b>malfind</b> ищет процессы с анонимным или исполняемым регионом памяти, в который не отображается образ, — типичный признак инъекции кода (process hollowing, reflective DLL).</p>`,

  phh_replyto: `<p><span class="yes">Верно:</span> подмена <b>Reply-To</b> перенаправляет ответы на чужой домен: письмо приходит с «финансов», но ответ уйдёт злоумышленнику. Сравнивайте адрес для ответа с адресом отправителя.</p>`,

  bta_tactic: `<p><span class="yes">Верно:</span> <b>тактика</b> отвечает на «зачем» (Initial Access, Persistence, Exfiltration), а <b>техника</b> — на «как» (PowerShell, LSASS dump). Поэтому в ATT&amp;CK выстроена иерархия: тактика → техника → подтехники.</p>`,
/* ---------- Новые задания: Windows / AD / реверс / аудит ---------- */
  wr_tri: `<p><span class="yes">Верно:</span> <code>AppData\\Local\\Temp</code> — временная папка. Там не живут автозапуски и легитимные службы, поэтому процесс оттуда с аргументом <code>-enc</code> — первое, что проверяют на триаже. Настоящий <code>svchost.exe</code> лежит в <code>System32</code>.</p>
    <p>Подпись и «принадлежность антивирусу» ничего не решают: вредонос маскируется под любые имена, а подпись может отсутствовать.</p>`,

  wr_autorun: `<p><span class="yes">Верно:</span> ветка <code>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run</code> добавляет автозапуск для текущего пользователя. Есть и соседние точки: <code>HKLM\\…\\Run</code> (для всех пользователей), <code>RunOnce</code>, Startup-папка, задачи и службы — при расследовании проверяют их все.</p>`,

  wr_enc: `<p><span class="yes">Верно:</span> <code>-w hidden</code> прячет окно, <code>-enc</code> передаёт команду в base64. Вместе это означает «пользователь ничего не видит, а содержимое команды не читается глазами» — типичная упаковка payload. Штатные обновления и справка так не запускаются, а BitLocker к PowerShell отношения не имеет.</p>`,

  adr_path: `<p><span class="yes">Верно:</span> если учётка состоит в группе, которая есть на самом контроллере домена, то на этом же DC менялся пароль доменного администратора — а значит, там есть резервная копия <code>ntds.dit</code>. Её чтение даёт хеши всех учёток домена, то есть мгновенный путь к Domain Admin (а после этого — и к любому ресурсу через Kerberos).</p>`,

  adr_ntds: `<p><span class="yes">Верно:</span> <b>NTDS.dit</b> — база Active Directory (файл лежит в <code>C:\\Windows\\NTDS</code>). В ней учётки, хеши паролей, политики и история: одна копия фактически означает контроль над доменом.</p>
    <p>Поэтому контроллер домена — цель №1, его резервные копии должны храниться отдельно и защищаться, а скомпрометированный DC требует переустановки, а не «лечения на месте».</p>`,

  hda_logon: `<p><span class="yes">Верно:</span> <b>4624</b> — успешный вход, <b>4625</b> — неудачный. Вместе они дают картину: всплеск 4625 с одного адреса, а затем 4624 с типами 3 (сеть) или 10 (RDP) — типичная картина перебора с последующим успехом.</p>`,

  hda_proc: `<p><span class="yes">Верно:</span> <b>4688</b> записывает создание процесса с командной строкой. Это позволяет увидеть <code>powershell -w hidden -enc …</code> или запуск из <code>Temp</code> задним числом. Аудит создания процессов по умолчанию выключен — его включают политикой безопасности, и именно на нём держится охота (hunting).</p>`,

  hda_sbl: `<p><span class="yes">Верно:</span> Script Block Logging (4104) пишет тело выполняемого блока PowerShell, поэтому base64-обёртка перестаёт быть защитой: аналитик видит реальную команду. Остальные варианты — про производительность, подписи и шифрование, это другая функциональность.</p>`,

  hda_clear: `<p><span class="yes">Верно:</span> <b>1102</b> — «журнал безопасности очищен». В расследовании это самостоятельная улика: если легитимный администратор чистит лог только по процедуре, то неожиданное 1102 указывает на anti-forensics. Заодно проверьте, кто именно выполнил очистку и не менялись ли размеры журналов.</p>`,
};

/* Навешиваем разборы на задания */
(function applyExplanations() {
  if (typeof COURSES === "undefined" || !EXPLANATIONS) return;
  const missing = [];
  const used = new Set();
  COURSES.forEach((c) => (c.rooms || []).forEach((r) => (r.tasks || []).forEach((t) => {
    if (EXPLANATIONS[t.id]) { t.explanation = EXPLANATIONS[t.id]; used.add(t.id); }
  })));
  Object.keys(EXPLANATIONS).forEach((id) => { if (!used.has(id)) missing.push(id); });
  // Разбор без задания — опечатка в id; сообщаем, чтобы потеря не была тихой
  if (missing.length && typeof console !== "undefined") console.warn("[CyberPath] explanation без задания:", missing);
  if (typeof window !== "undefined") window.EXPLANATIONS = EXPLANATIONS;
})();